double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const int w1_size = n_hidden * n_in;
    const int b1_off = w1_size;
    const int w2_off = b1_off + n_hidden;
    const int b2_off = w2_off + n_hidden;
    const int total = b2_off + 1;

    for (int i = 0; i < total; ++i) {
        grad[i] = 0.0;
    }

    if (n_samples <= 0) {
        return 0.0;
    }

    const double* W1 = params;
    const double* b1 = params + b1_off;
    const double* W2 = params + w2_off;
    const double b2 = params[b2_off];

    const double inv_n = 1.0 / static_cast<double>(n_samples);
    double loss_sum = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        const double target = y[s];

        double z = b2;
        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            const double* w1j = W1 + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                a += w1j[k] * x[k];
            }
            double h = std::tanh(a);
            z += W2[j] * h;
        }

        double p;
        double loss;

        if (z >= 0.0) {
            double e = std::exp(-z);
            p = 1.0 / (1.0 + e);
            if (target > 0.5) {
                loss = std::log1p(e);
            } else {
                loss = z + std::log1p(e);
            }
        } else {
            double e = std::exp(z);
            p = e / (1.0 + e);
            if (target > 0.5) {
                loss = -z + std::log1p(e);
            } else {
                loss = std::log1p(e);
            }
        }

        loss_sum += loss * inv_n;

        double delta = (p - target) * inv_n;
        grad[b2_off] += delta;

        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            const double* w1j = W1 + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                a += w1j[k] * x[k];
            }
            double h = std::tanh(a);

            grad[w2_off + j] += delta * h;

            double dz1 = delta * W2[j] * (1.0 - h * h);
            grad[b1_off + j] += dz1;

            double* gW1 = grad + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                gW1[k] += dz1 * x[k];
            }
        }
    }

    return loss_sum;
}

